def total_duration(playlist):
    """Returns the total duration in seconds across all songs."""
    return sum(song['duration'] for song in playlist)

def find_by_artist(playlist, artist):
    """Returns a list of song titles by the given artist."""
    return [song['title'] for song in playlist if song['artist'] == artist]

def sort_by_duration(playlist):
    """Returns the playlist sorted from shortest to longest song."""
    return sorted(playlist, key=lambda song: song['duration'])
